#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "audio_effects.h"
#include "td_psola_autotune.h"

typedef struct
{
    uint32_t sample_rate;
    uint16_t channels;
    uint16_t bits_per_sample;
    uint32_t data_size;
    long data_offset;
} WavInfo;

typedef enum
{
    DEMO_EFFECT_TD_PSOLA_AUTOTUNE = 0,
    DEMO_EFFECT_LEGACY_AUTOTUNE,
    DEMO_EFFECT_BLOCK_EFFECT
} DemoEffectKind;

typedef struct
{
    DemoEffectKind kind;
    AudioEffectMode block_mode;
    float psola_strength;
} DemoEffect;

static uint16_t read_u16_le(FILE *f)
{
    uint8_t b[2];
    if (fread(b, 1U, 2U, f) != 2U) return 0U;
    return (uint16_t)((uint16_t)b[0] | ((uint16_t)b[1] << 8U));
}

static uint32_t read_u32_le(FILE *f)
{
    uint8_t b[4];
    if (fread(b, 1U, 4U, f) != 4U) return 0U;
    return (uint32_t)b[0]
         | ((uint32_t)b[1] << 8U)
         | ((uint32_t)b[2] << 16U)
         | ((uint32_t)b[3] << 24U);
}

static void write_u16_le(FILE *f, uint16_t value)
{
    const uint8_t b[2] = {
        (uint8_t)(value & 0xFFU),
        (uint8_t)((value >> 8U) & 0xFFU)
    };
    (void)fwrite(b, 1U, 2U, f);
}

static void write_u32_le(FILE *f, uint32_t value)
{
    const uint8_t b[4] = {
        (uint8_t)(value & 0xFFU),
        (uint8_t)((value >> 8U) & 0xFFU),
        (uint8_t)((value >> 16U) & 0xFFU),
        (uint8_t)((value >> 24U) & 0xFFU)
    };
    (void)fwrite(b, 1U, 4U, f);
}

static int parse_wav(FILE *f, WavInfo *info)
{
    char id[4];
    char wave[4];
    int found_fmt = 0;
    int found_data = 0;
    uint16_t audio_format = 0U;

    if ((f == NULL) || (info == NULL)) return 0;
    memset(info, 0, sizeof(*info));

    if (fread(id, 1U, 4U, f) != 4U || memcmp(id, "RIFF", 4U) != 0) return 0;
    (void)read_u32_le(f);
    if (fread(wave, 1U, 4U, f) != 4U || memcmp(wave, "WAVE", 4U) != 0) return 0;

    while ((!found_fmt || !found_data) && fread(id, 1U, 4U, f) == 4U)
    {
        const uint32_t chunk_size = read_u32_le(f);
        const long chunk_start = ftell(f);
        if (chunk_start < 0L) return 0;

        if (memcmp(id, "fmt ", 4U) == 0)
        {
            if (chunk_size < 16U) return 0;
            audio_format = read_u16_le(f);
            info->channels = read_u16_le(f);
            info->sample_rate = read_u32_le(f);
            (void)read_u32_le(f);
            (void)read_u16_le(f);
            info->bits_per_sample = read_u16_le(f);
            found_fmt = 1;
        }
        else if (memcmp(id, "data", 4U) == 0)
        {
            info->data_size = chunk_size;
            info->data_offset = ftell(f);
            if (info->data_offset < 0L) return 0;
            found_data = 1;
        }

        if (found_data) break;

        {
            const long next_chunk = chunk_start + (long)chunk_size + (long)(chunk_size & 1U);
            if (fseek(f, next_chunk, SEEK_SET) != 0) return 0;
        }
    }

    return found_fmt && found_data && (audio_format == 1U);
}

static int write_wav_header(FILE *f, uint32_t data_size)
{
    const uint16_t channels = 1U;
    const uint16_t bits = 16U;
    const uint32_t sample_rate = AUDIO_EFFECTS_SAMPLE_RATE_HZ;
    const uint16_t block_align = (uint16_t)(channels * (bits / 8U));
    const uint32_t byte_rate = sample_rate * (uint32_t)block_align;

    if (fwrite("RIFF", 1U, 4U, f) != 4U) return 0;
    write_u32_le(f, 36U + data_size);
    if (fwrite("WAVE", 1U, 4U, f) != 4U) return 0;
    if (fwrite("fmt ", 1U, 4U, f) != 4U) return 0;
    write_u32_le(f, 16U);
    write_u16_le(f, 1U);
    write_u16_le(f, channels);
    write_u32_le(f, sample_rate);
    write_u32_le(f, byte_rate);
    write_u16_le(f, block_align);
    write_u16_le(f, bits);
    if (fwrite("data", 1U, 4U, f) != 4U) return 0;
    write_u32_le(f, data_size);
    return 1;
}

static int effect_from_string(const char *text, DemoEffect *effect)
{
    if ((text == NULL) || (effect == NULL)) return 0;

    if (strcmp(text, "autotune") == 0)
    {
        effect->kind = DEMO_EFFECT_TD_PSOLA_AUTOTUNE;
        effect->block_mode = AUDIO_EFFECT_AUTOTUNE;
        effect->psola_strength = 0.90f;
    }
    else if (strcmp(text, "autotune-soft") == 0)
    {
        effect->kind = DEMO_EFFECT_TD_PSOLA_AUTOTUNE;
        effect->block_mode = AUDIO_EFFECT_AUTOTUNE;
        effect->psola_strength = 0.65f;
    }
    else if (strcmp(text, "autotune-hard") == 0)
    {
        effect->kind = DEMO_EFFECT_TD_PSOLA_AUTOTUNE;
        effect->block_mode = AUDIO_EFFECT_AUTOTUNE;
        effect->psola_strength = 1.0f;
    }
    else if (strcmp(text, "autotune-legacy") == 0)
    {
        effect->kind = DEMO_EFFECT_LEGACY_AUTOTUNE;
        effect->block_mode = AUDIO_EFFECT_AUTOTUNE;
        effect->psola_strength = 0.0f;
    }
    else
    {
        effect->kind = DEMO_EFFECT_BLOCK_EFFECT;
        effect->psola_strength = 0.0f;
        if (strcmp(text, "pitch-up") == 0) effect->block_mode = AUDIO_EFFECT_PITCH_UP;
        else if (strcmp(text, "pitch-down") == 0) effect->block_mode = AUDIO_EFFECT_PITCH_DOWN;
        else if (strcmp(text, "robot") == 0) effect->block_mode = AUDIO_EFFECT_ROBOT;
        else if (strcmp(text, "echo") == 0) effect->block_mode = AUDIO_EFFECT_ECHO;
        else if (strcmp(text, "reverb") == 0) effect->block_mode = AUDIO_EFFECT_REVERB;
        else return 0;
    }
    return 1;
}

static void print_usage(const char *program)
{
    fprintf(stderr,
            "Usage: %s <input.wav> <output.wav> <effect>\n"
            "Effects:\n"
            "  autotune         NEW TD-PSOLA, 90%% correction strength\n"
            "  autotune-soft    NEW TD-PSOLA, 65%% correction strength\n"
            "  autotune-hard    NEW TD-PSOLA, 100%% correction strength\n"
            "  autotune-legacy  previous granular-delay autotune\n"
            "  pitch-up, pitch-down, robot, echo, reverb\n"
            "Input must be 48 kHz, mono, 16-bit PCM WAV.\n",
            program);
}

static int process_td_psola(FILE *input_file, FILE *output_file, const WavInfo *wav, float strength)
{
    const size_t sample_count = (size_t)(wav->data_size / 2U);
    int16_t *input = (int16_t *)malloc(sample_count * sizeof(int16_t));
    int16_t *output = (int16_t *)malloc(sample_count * sizeof(int16_t));
    if ((input == NULL) || (output == NULL))
    {
        fprintf(stderr, "Could not allocate host buffers for TD-PSOLA comparison.\n");
        free(input);
        free(output);
        return 0;
    }

    if (fread(input, sizeof(int16_t), sample_count, input_file) != sample_count)
    {
        fprintf(stderr, "Unexpected end of WAV data.\n");
        free(input);
        free(output);
        return 0;
    }

    TdPsolaConfig config;
    TdPsolaStats stats;
    TdPsola_DefaultConfig(&config);
    config.strength = strength;

    const TdPsolaStatus status = TdPsola_ProcessBuffer(input, output, sample_count, &config, &stats);
    if (status != TD_PSOLA_STATUS_OK)
    {
        fprintf(stderr, "TD-PSOLA processing failed with status %d.\n", (int)status);
        free(input);
        free(output);
        return 0;
    }

    if (fwrite(output, sizeof(int16_t), sample_count, output_file) != sample_count)
    {
        fprintf(stderr, "Could not write output samples.\n");
        free(input);
        free(output);
        return 0;
    }

    fprintf(stdout,
            "TD-PSOLA analysis: %zu frames, %zu voiced (%.1f%%), mean detected %.1f Hz, "
            "mean target %.1f Hz, ratio range %.4f..%.4f\n",
            stats.analysis_frames,
            stats.voiced_frames,
            (stats.analysis_frames > 0U)
                ? 100.0 * (double)stats.voiced_frames / (double)stats.analysis_frames
                : 0.0,
            (double)stats.mean_detected_pitch_hz,
            (double)stats.mean_target_pitch_hz,
            (double)stats.minimum_applied_ratio,
            (double)stats.maximum_applied_ratio);

    free(input);
    free(output);
    return 1;
}

static int process_block_effect(FILE *input_file,
                                FILE *output_file,
                                const WavInfo *wav,
                                AudioEffectMode mode,
                                int print_autotune_diagnostics)
{
    AudioEffectsState effects;
    int16_t input[AUDIO_EFFECTS_MAX_BLOCK_SIZE];
    int16_t output[AUDIO_EFFECTS_MAX_BLOCK_SIZE];
    uint32_t samples_remaining = wav->data_size / 2U;
    uint32_t samples_processed = 0U;
    uint32_t next_diag_sample = AUDIO_EFFECTS_SAMPLE_RATE_HZ;

    AudioEffects_Init(&effects);
    if (AudioEffects_SetMode(&effects, mode) != AUDIO_EFFECTS_STATUS_OK) return 0;

    while (samples_remaining > 0U)
    {
        const size_t requested = (samples_remaining > AUDIO_EFFECTS_MAX_BLOCK_SIZE)
                               ? AUDIO_EFFECTS_MAX_BLOCK_SIZE
                               : (size_t)samples_remaining;
        const size_t count = fread(input, sizeof(int16_t), requested, input_file);
        if (count != requested) return 0;

        if (AudioEffects_ProcessBlock(&effects, input, output, count) != AUDIO_EFFECTS_STATUS_OK)
            return 0;
        if (fwrite(output, sizeof(int16_t), count, output_file) != count) return 0;

        samples_remaining -= (uint32_t)count;
        samples_processed += (uint32_t)count;

        if (print_autotune_diagnostics && (samples_processed >= next_diag_sample))
        {
            const AudioEffectsDiagnostics d = AudioEffects_GetDiagnostics(&effects);
            fprintf(stdout,
                    "%.1f s legacy: detected %.1f Hz, target %.1f Hz, confidence %.2f, ratio %.4f\n",
                    (double)samples_processed / (double)AUDIO_EFFECTS_SAMPLE_RATE_HZ,
                    (double)d.detected_pitch_hz,
                    (double)d.target_pitch_hz,
                    (double)d.detector_confidence,
                    (double)d.applied_pitch_ratio);
            next_diag_sample += AUDIO_EFFECTS_SAMPLE_RATE_HZ;
        }
    }
    return 1;
}

int main(int argc, char **argv)
{
    FILE *input_file = NULL;
    FILE *output_file = NULL;
    WavInfo wav;
    DemoEffect effect;
    int result = EXIT_FAILURE;

    if (argc != 4)
    {
        print_usage(argv[0]);
        return EXIT_FAILURE;
    }
    if (!effect_from_string(argv[3], &effect))
    {
        fprintf(stderr, "Unknown effect: %s\n", argv[3]);
        print_usage(argv[0]);
        return EXIT_FAILURE;
    }

    input_file = fopen(argv[1], "rb");
    if (input_file == NULL)
    {
        perror("Could not open input WAV");
        goto cleanup;
    }
    if (!parse_wav(input_file, &wav))
    {
        fprintf(stderr, "Input is not a supported PCM WAV file.\n");
        goto cleanup;
    }
    if ((wav.sample_rate != AUDIO_EFFECTS_SAMPLE_RATE_HZ)
        || (wav.channels != 1U)
        || (wav.bits_per_sample != 16U)
        || ((wav.data_size & 1U) != 0U))
    {
        fprintf(stderr,
                "Unsupported WAV format: %u Hz, %u channel(s), %u bit.\n"
                "Required: 48000 Hz, mono, 16-bit PCM.\n",
                (unsigned)wav.sample_rate,
                (unsigned)wav.channels,
                (unsigned)wav.bits_per_sample);
        goto cleanup;
    }

    output_file = fopen(argv[2], "wb");
    if (output_file == NULL)
    {
        perror("Could not open output WAV");
        goto cleanup;
    }
    if (!write_wav_header(output_file, wav.data_size))
    {
        fprintf(stderr, "Could not write output WAV header.\n");
        goto cleanup;
    }

    if (effect.kind == DEMO_EFFECT_TD_PSOLA_AUTOTUNE)
    {
        if (!process_td_psola(input_file, output_file, &wav, effect.psola_strength)) goto cleanup;
    }
    else
    {
        const int print_diag = (effect.kind == DEMO_EFFECT_LEGACY_AUTOTUNE) ? 1 : 0;
        if (!process_block_effect(input_file, output_file, &wav, effect.block_mode, print_diag))
        {
            fprintf(stderr, "Block effect processing failed.\n");
            goto cleanup;
        }
    }

    fprintf(stdout,
            "Processed %.2f seconds with effect '%s' -> %s\n",
            (double)(wav.data_size / 2U) / (double)AUDIO_EFFECTS_SAMPLE_RATE_HZ,
            argv[3],
            argv[2]);
    result = EXIT_SUCCESS;

cleanup:
    if (output_file != NULL) fclose(output_file);
    if (input_file != NULL) fclose(input_file);
    return result;
}
